"""Post-process an Alembic autogenerated migration for Postgres:

- every `sa.Enum(..., name='x')` becomes a shared `postgresql.ENUM(..., create_type=False)` that is
  created once before the tables (and dropped at the end of downgrade), so an enum used by several
  columns/tables is never created twice;
- row-level security is enabled on every created table (deny-all for Supabase's anon roles);
- the pgvector import is added when vector columns are used.

Usage: uv run python scripts/fix_migration.py alembic/versions/0003_*.py
"""

import re
import sys
from pathlib import Path

ENUM_RE = re.compile(r"sa\.Enum\(((?:'[^']*',\s*)+)name='([a-z_]+)'\)")


def fix(path: Path) -> None:
    src = path.read_text()
    enums: dict[str, list[str]] = {}

    def repl(m: re.Match[str]) -> str:
        values = re.findall(r"'([^']*)'", m.group(1))
        enums.setdefault(m.group(2), values)
        return f"{m.group(2)}_enum"

    src = ENUM_RE.sub(repl, src)
    tables = re.findall(r"op\.create_table\('([a-z_]+)'", src)

    header = "".join(
        f"{name}_enum = postgresql.ENUM({', '.join(repr(v) for v in values)}, name={name!r}, create_type=False)\n"
        for name, values in enums.items()
    )
    if "from sqlalchemy.dialects import postgresql" not in src:
        src = src.replace(
            "import sqlalchemy as sa\n", "import sqlalchemy as sa\nfrom sqlalchemy.dialects import postgresql\n", 1
        )
    if "pgvector" in src and "import pgvector.sqlalchemy" not in src:
        src = src.replace("import sqlalchemy as sa\n", "import pgvector.sqlalchemy\nimport sqlalchemy as sa\n", 1)
    src = src.replace("# revision identifiers", header + "\n# revision identifiers", 1)

    creates = "".join(f"    {name}_enum.create(op.get_bind(), checkfirst=True)\n" for name in enums)
    rls = "".join(f"    op.execute('ALTER TABLE {t} ENABLE ROW LEVEL SECURITY')\n" for t in tables)
    drops = "".join(f"    {name}_enum.drop(op.get_bind(), checkfirst=True)\n" for name in enums)

    up_start = src.index('    """Upgrade schema."""\n') + len('    """Upgrade schema."""\n')
    src = src[:up_start] + creates + src[up_start:]
    src = src.replace("    # ### end Alembic commands ###\n\n\ndef downgrade", rls + "\n\ndef downgrade", 1)
    src = re.sub(r"    # ### end Alembic commands ###\s*$", drops, src)
    src = src.replace("    # ### commands auto generated by Alembic - please adjust! ###\n", "")
    path.write_text(src)
    print(f"{path.name}: {len(enums)} enums, {len(tables)} tables")


if __name__ == "__main__":
    for arg in sys.argv[1:]:
        fix(Path(arg))
